import {moneyValue,installMoneyInputs} from './money-input.js?v=money-pots-20261103';
import {controls,purposes,otherControl,reserveSummary,potBalance,potSpent} from './controls.js?v=money-pots-20261103';
import {planningSummary} from './planning.js?v=money-pots-20261103';
import {helpTopics,searchHelp} from './help.js?v=money-pots-20261103';
import {initLayout} from './layout.js?v=money-pots-20261103';
import {resetModes,planReset} from './reset.js?v=money-pots-20261103';
import * as F from './finance.js?v=money-pots-20261103';
import * as Store from './storage.js?v=money-pots-20261103';
const $=id=>document.getElementById(id), e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=F.emptyState(),ready=false,view='dashboard',editorKind='',editing=null,period=F.today().slice(0,7),query='',typeFilter='all',statusFilter='all';
let manualLoginPending=false,entrySequence=0;
let links=[],reloadSequence=0,editorControl=null,editorSaving=false,allocationMode='reserve';
const layout=initLayout();
installMoneyInputs(document);
const views={dashboard:['◫','Visão geral','Seu dinheiro, com clareza.'],transactions:['⇄','Lançamentos','Receitas, despesas e movimentações em um só lugar.'],payables:['◷','Contas a pagar','Contas fixas, vencimentos e faturas do controle selecionado.'],pots:['▣','Potes e reservas','Separe o dinheiro por finalidade, sem duplicar o saldo.'],between:['⇄','Entre controles','Pró-labore, lucros, aportes e reembolsos vinculados.'],future:['◷','Compromissos','Organize o que você ainda tem a pagar e receber.'],accounts:['▤','Contas','Seus saldos de abertura e o dinheiro em cada conta.'],cards:['▱','Cartões e faturas','Compras, parcelas e pagamentos sem duplicar despesas.'],budgets:['◉','Orçamento','Dê um destino ao seu dinheiro antes de gastar.'],goals:['⚑','Metas','Um plano para cada conquista.'],investments:['↗','Investimentos','Acompanhe suas reservas, aportes e rendimentos.'],calculators:['∑','Calculadoras','Experimente possibilidades antes de decidir.'],categories:['≡','Categorias','Organize seus lançamentos do seu jeito.'],reports:['▧','Relatórios','Consulte, imprima e exporte seus registros.'],help:['?','Ajuda','Entenda cada recurso e organize seus próximos passos.'],settings:['⚙','Configurações','Reinicie seu controle financeiro com segurança.']};
const accountKinds={checking:'Conta corrente',cash:'Carteira',saving:'Poupança / reserva',investment:'Investimento'};
const txKinds={income:'Receita',expense:'Despesa',card:'Compra no cartão',invoicePayment:'Pagamento de fatura',transfer:'Transferência',yield:'Rendimento',interIn:'Entrada de outro controle',interOut:'Saída para outro controle'};
const txLabel=t=>t.linkId?(txKinds[t.kind]+' · '+(purposes[t.purpose]||'')):txKinds[t.kind];
const name=(k,id)=>state[k].find(x=>x.id===id)?.name||'—';
const amt=n=>'<span class="'+(n<0?'negative':'')+'">'+F.money(n)+'</span>';
const date=d=>d?d.split('-').reverse().join('/'):'—';
const badge=(text,style='')=>'<span class="badge '+style+'">'+e(text)+'</span>';
const status=t=>t.status==='cancelled'?badge('Cancelado','gray'):t.status==='planned'?badge(t.dueDate<F.today()?'Atrasado':'Previsto',t.dueDate<F.today()?'red':'amber'):badge(t.kind==='card'?'Confirmado':t.kind==='income'||t.kind==='yield'||t.kind==='interIn'?'Recebido':'Pago');
const action=(text,act,id='',cls='')=>'<button class="'+cls+'" data-action="'+act+'" data-id="'+e(id)+'">'+text+'</button>';
const metric=(title,value,note,icon='↗',dark=false)=>'<div class="metric '+(dark?'dark':'')+'"><div class="metric-top"><span class="metric-title">'+title+'</span><span class="metric-icon">'+icon+'</span></div><div class="metric-value">'+F.money(value)+'</div><div class="metric-note">'+note+'</div></div>';
const empty=(title,note='Cadastre seu primeiro registro para começar.')=>'<div class="empty"><span style="font-size:28px">◌</span><strong>'+title+'</strong><p>'+note+'</p></div>';
function notice(text,success=false){$('status-message').textContent=text;$('status-message').classList.toggle('success',success);$('status-message').hidden=!text;}
function loginDeadline(promise,milliseconds,code){
 let timer;
 const waiting=new Promise((resolve,reject)=>{timer=setTimeout(()=>{const error=new Error(code);error.code=code;reject(error);},milliseconds);});
 return Promise.race([promise,waiting]).finally(()=>clearTimeout(timer));
}
function errorText(err){if(err?.code==='app/access-timeout')return 'O e-mail e a senha foram aceitos, mas o Firestore não respondeu à verificação de acesso. Confira a conexão, as regras publicadas e authorized_users/UID com enabled=true; depois tente novamente.';if(err?.code==='app/data-timeout')return 'O login foi aceito, mas os dados do Firestore demoraram para carregar. Confira a conexão e clique em Atualizar.';if(err?.code==='app/connection-timeout')return 'A conexão inicial com o Firebase demorou demais. Confira sua internet e recarregue com Ctrl+F5. A demonstração continua disponível.';if(err?.code==='app/access-not-approved')return 'Acesso não autorizado. Peça ao administrador para liberar seu UID em authorized_users no Firebase.';if(err?.code==='auth/user-disabled')return 'Seu usuário foi desativado. Entre em contato com o administrador.';if(err?.code==='auth/user-not-found'||err?.code==='auth/wrong-password')return 'E-mail ou senha incorretos. O cadastro é feito pelo administrador.';if(err?.code==='auth/invalid-api-key'||err?.code==='auth/api-key-not-valid.-please-pass-a-valid-api-key.')return 'A configuração do Firebase está inválida. Informe o administrador.';if(err?.code==='auth/operation-not-allowed')return 'O login por e-mail e senha precisa estar ativado no Firebase Authentication.';if(err?.code==='auth/network-request-failed')return 'Falha de conexão. Confira a internet e tente novamente.';if(err?.code==='auth/too-many-requests')return 'Muitas tentativas de login. Aguarde antes de tentar novamente.';if(err?.code==='permission-denied')return 'O Firebase recusou o acesso. Publique as novas regras firestore.rules da versão Pessoal/Empresa no Console do Firebase → Firestore → Regras. Depois clique em Atualizar.';if(err?.code==='auth/invalid-credential')return 'E-mail ou senha incorretos.';if(err?.code==='auth/email-already-in-use')return 'Este e-mail já possui cadastro.';if(err?.code==='auth/weak-password')return 'Use uma senha com pelo menos seis caracteres.';if(err?.code==='auth/unauthorized-domain')return 'Autorize o domínio do GitHub Pages no Firebase Authentication.';return err?.message||'Não foi possível concluir a operação.';}
function drawNav(){syncControlHeader(); $('nav-main').innerHTML=Object.entries(views).map(([key,v])=>'<button data-view="'+key+'" class="'+(view===key?'active':'')+'" aria-label="'+e(v[1])+'" title="'+e(v[1])+'" '+(view===key?'aria-current="page"':'')+'><span class="nav-icon" aria-hidden="true">'+v[0]+'</span><span class="nav-text">'+e(v[1])+'</span></button>').join('');$('breadcrumb').textContent=views[view][1].toLocaleUpperCase('pt-BR');}
function heading(extra=''){return '<div class="page-heading"><div><span class="control-eyebrow">'+e(controls[Store.currentControl()])+'</span><h1>'+views[view][1]+'</h1><p>'+views[view][2]+'</p></div><div class="heading-actions">'+extra+'</div></div>';}
const monthInput=()=>'<input aria-label="Mês de referência" class="period-select" id="period" type="month" value="'+period+'">';
function chart(rows){const values=rows.map(r=>r.balance/100),min=Math.min(0,...values),max=Math.max(1,...values),span=max-min||1;const x=i=>24+i*(570/Math.max(1,rows.length-1)),y=v=>155-(v-min)/span*120;const pts=values.map((v,i)=>x(i)+','+y(v)).join(' ');const area='24,170 '+pts+' 594,170';return '<svg class="chart" viewBox="0 0 620 210" role="img" aria-label="Projeção do saldo disponível para os próximos doze meses"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#117f72" stop-opacity=".18"/><stop offset="100%" stop-color="#117f72" stop-opacity=".01"/></linearGradient></defs>'+[35,75,115,155].map(y=>'<line x1="24" y1="'+y+'" x2="594" y2="'+y+'" stroke="#edf1ee"/>').join('')+'<polygon points="'+area+'" fill="url(#fill)"/><polyline points="'+pts+'" stroke="#117f72" stroke-width="3" fill="none" stroke-linecap="round" stroke-linejoin="round"/>'+values.map((v,i)=>'<circle cx="'+x(i)+'" cy="'+y(v)+'" r="3" fill="#117f72"><title>'+F.monthLabel(rows[i].month)+': '+F.money(rows[i].balance)+'</title></circle>').join('')+rows.filter((_,i)=>i%2===0||i===rows.length-1).map(r=>{const i=rows.indexOf(r);return '<text x="'+x(i)+'" y="195" text-anchor="middle">'+e(F.monthLabel(r.month))+'</text>';}).join('')+'</svg>';}
function recentRows(txs){return txs.length?'<div class="table-wrap"><table><thead><tr><th>Descrição</th><th>Data</th><th>Situação</th><th class="right">Valor</th></tr></thead><tbody>'+txs.map(t=>'<tr><td><strong>'+e(t.description)+'</strong><small>'+e(txLabel(t))+' · '+e(name('categories',t.category))+'</small></td><td>'+date(t.date)+'</td><td>'+status(t)+'</td><td class="right">'+amt(t.amountCents)+'</td></tr>').join('')+'</tbody></table></div>':empty('Seu histórico começa aqui');}
function dashboard(){
 const b=F.balances(state),proj=F.forecast(state),plan=planningSummary(state,period),label=F.monthLabel(period);
 const liquid=state.accounts.filter(a=>a.kind!=='investment').reduce((v,a)=>v+b[a.id],0),invested=state.accounts.filter(a=>a.kind==='investment').reduce((v,a)=>v+b[a.id],0);
 const paid=state.transactions.filter(t=>t.status==='posted'&&t.paidDate?.startsWith(period)&&t.kind!=='card');
 const income=paid.filter(t=>['income','yield','interIn'].includes(t.kind)).reduce((v,t)=>v+t.amountCents,0),expense=paid.filter(t=>['expense','invoicePayment','interOut'].includes(t.kind)).reduce((v,t)=>v+t.amountCents,0);
 const due=plan.items;const reserves=reserveSummary(state);
 return heading(monthInput()+action('Como interpretar?','goto-help','','secondary compact'))+
 '<div class="metrics">'+metric('Saldo nas contas',liquid,'Saldo de hoje · inclui valores reservados','▤',true)+metric('Recebido no mês',income,'Baixas em '+label,'↙')+metric('Saídas pagas no mês',expense,'Despesas, faturas e saídas entre controles · '+label,'↗')+metric('Patrimônio investido',invested,'Separado do dinheiro disponível','⌁')+'</div>'+
 '<section class="panel control-reserves"><div><strong>Reservado nos potes: '+F.money(reserves.reserved)+'</strong><p>Saldo ainda não reservado: '+F.money(reserves.unallocated)+'. As reservas já fazem parte do saldo das contas.</p></div>'+action('Ver potes →','goto-pots','','secondary compact')+'</section>'+
 '<section class="planning-section" aria-labelledby="planning-month-title"><div class="panel-header"><div><h2 id="planning-month-title">O que vem pela frente</h2><p>Pendências atuais com vencimento em '+e(label)+'. Valores pagos ou cancelados ficam de fora.</p></div>'+badge(label)+'</div>'+
 '<div class="metrics future-metrics">'+metric('A receber no mês',plan.income,'Receitas e rendimentos ainda previstos','↙')+metric('Contas a pagar no mês',plan.expenses,'Despesas e saídas entre controles pendentes','◷')+metric('Faturas em aberto no mês',plan.invoices,'Saldo restante dos cartões','▱')+metric('Total a pagar no mês',plan.toPay,'Contas pendentes + faturas abertas','↗',true)+'</div>'+
 '<div class="planning-highlights"><div class="panel"><span class="metric-title">Saldo disponível projetado no fim de '+e(label)+'</span><div class="metric-value">'+(plan.projection?amt(plan.projection.balance):'—')+'</div><p class="panel-note">'+(plan.projection?'Parte do disponível hoje, com previsões, faturas e aportes/resgates pendentes.':period<F.today().slice(0,7)?'Não calculamos projeção retroativa. Selecione o mês atual ou um futuro.':'Este mês está fora do horizonte de projeção de 120 meses.')+'</p></div>'+
 '<div class="panel"><span class="metric-title">Todos os compromissos de hoje em diante</span><div class="metric-value">'+F.money(plan.futureTotal)+'</div><p class="panel-note">'+plan.futureCount+' compromisso(s) registrado(s)'+(plan.lastFutureDate?' até '+date(plan.lastFutureDate):'')+'. Inclui datas além da tabela de 12 meses; não inclui novas contas ainda não cadastradas.</p></div></div>'+
 (plan.overdueTotal?'<div class="planning-overdue"><strong>Também há '+F.money(plan.overdueTotal)+' em pagamentos vencidos.</strong> Esse total é separado dos compromissos de hoje em diante. A projeção inclui vencidos no primeiro mês.</div>':'')+'</section>'+
 '<div class="grid-two section-gap"><section class="panel"><div class="panel-header"><div><h3>Olhe para os próximos meses</h3><p>Projeção do disponível, começando no mês atual</p></div>'+badge('12 meses')+'</div>'+chart(proj)+'<div class="chart-legend"><span><i class="legend-dot"></i>Saldo projetado</span><span>Menor saldo: <strong>'+F.money(Math.min(...proj.map(r=>r.balance)))+'</strong></span></div></section>'+
 '<section class="panel"><div class="panel-header"><div><h3>Próximos vencimentos</h3><p>A pagar e a receber em '+e(label)+'</p></div>'+action('Ver todos ('+due.length+') →','goto-future','','text-button')+'</div>'+
 (due.length?due.slice(0,6).map(t=>'<div class="mini-row"><div class="mini-icon">'+(t.incoming?'↙':'↗')+'</div><div class="grow"><strong>'+e(t.kind==='invoice'?'Fatura '+name('cards',t.cardId):t.description)+'</strong><small>'+date(t.dueDate)+' · '+(t.incoming?'A receber':t.kind==='invoice'?'Fatura a pagar':'Despesa a pagar')+(t.dueDate<F.today()?' · Vencido':'')+'</small></div><span class="amount '+(t.incoming?'positive':'negative')+'">'+F.money(t.amount)+'</span></div>').join(''):empty('Nenhuma pendência neste mês','Escolha outro mês ou cadastre seus próximos compromissos.'))+'</section></div>'+
 '<section class="panel planning-table"><div class="panel-header"><div><h3>Seu planejamento mês a mês</h3><p>12 meses a partir de '+F.monthLabel(proj[0].month)+' · somente compromissos registrados</p></div></div><div class="table-wrap"><table><thead><tr><th>Mês</th><th class="right">Saldo inicial</th><th class="right">Entradas previstas</th><th class="right">Saídas + aportes</th><th class="right">Faturas abertas</th><th class="right">Saldo final</th><th></th></tr></thead><tbody>'+
 proj.map(row=>'<tr><td><strong>'+F.monthLabel(row.month)+'</strong></td><td class="right">'+F.money(row.opening)+'</td><td class="right positive">'+F.money(row.incoming)+'</td><td class="right">'+F.money(row.outgoing)+'</td><td class="right">'+F.money(row.card)+'</td><td class="right"><strong>'+amt(row.balance)+'</strong></td><td>'+action('Ver','planning-month',row.month,'table-link')+'</td></tr>').join('')+'</tbody></table></div><p class="panel-note">A tabela projeta o dinheiro disponível, excluindo o saldo investido. Transferências previstas para investimentos são saídas; resgates são entradas. Os cartões entram pelo saldo aberto da fatura, sem somar novamente as compras ou os pagamentos. Vencidos são incorporados no primeiro mês.</p></section>'+
 '<div class="grid-two section-gap"><section class="panel"><div class="panel-header"><div><h3>Últimas movimentações</h3><p>Uma visão rápida do seu dia a dia</p></div>'+action('Ver histórico →','goto-transactions','','text-button')+'</div>'+recentRows([...state.transactions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5))+'</section><section class="panel"><div class="panel-header"><div><h3>Seus objetivos</h3><p>Transforme planos em próximos passos</p></div>'+action('＋','new-goals','','text-button')+'</div>'+(state.goals.length?state.goals.slice(0,3).map(g=>goalCard(g,true)).join(''):empty('Qual será sua próxima conquista?','Cadastre uma meta para acompanhar seu progresso.'))+'</section></div>'+
 (!state.accounts.length?'<div class="panel">Comece cadastrando uma conta e seu saldo de abertura. '+action('Cadastrar conta','new-accounts','','text-button')+'</div>':'');
}

function filters(){return '<div class="filters"><input id="period" type="month" aria-label="Mês" value="'+period+'"><input id="search" type="search" aria-label="Buscar lançamentos" placeholder="Buscar descrição ou categoria…" value="'+e(query)+'"><select id="filter-type" aria-label="Tipo"><option value="all">Todos os tipos</option>'+Object.entries(txKinds).map(([k,v])=>'<option value="'+k+'" '+(k===typeFilter?'selected':'')+'>'+v+'</option>').join('')+'</select><select id="filter-status" aria-label="Situação"><option value="all">Todas as situações</option>'+[['planned','Previstos'],['posted','Efetivados'],['cancelled','Cancelados']].map(([k,v])=>'<option value="'+k+'" '+(k===statusFilter?'selected':'')+'>'+v+'</option>').join('')+'</select></div>';}
function filtered(){return state.transactions.filter(t=>t.dueDate.startsWith(period)&&(view!=='future'||t.status==='planned')&&(typeFilter==='all'||t.kind===typeFilter)&&(statusFilter==='all'||t.status===statusFilter)&&(t.description+' '+name('categories',t.category)).toLowerCase().includes(query.toLowerCase())).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));}
function transactionTable(txs){return txs.length?'<div class="table-wrap"><table><thead><tr><th>Vencimento / baixa</th><th>Descrição / categoria</th><th>Conta / cartão</th><th>Situação</th><th class="right">Valor</th><th class="right">Ações</th></tr></thead><tbody>'+txs.map(t=>'<tr><td>'+date(t.dueDate)+'<small>'+(['card'].includes(t.kind)?'Fatura '+F.monthLabel(t.competence):t.paidDate?'Baixa '+date(t.paidDate):'Sem baixa')+'</small></td><td><strong>'+e(t.description)+'</strong><small>'+e(txLabel(t))+' · '+e(name('categories',t.category))+(t.installments>1?' · '+t.installment+'/'+t.installments:'')+'</small></td><td>'+e(['card','invoicePayment'].includes(t.kind)?name('cards',t.cardId):name('accounts',t.accountId))+(t.kind==='transfer'?'<small>→ '+e(name('accounts',t.toAccountId))+'</small>':'')+'</td><td>'+status(t)+'</td><td class="right">'+F.money(t.amountCents)+'</td><td><div class="row-actions">'+(t.status==='planned'?action('Baixar','settle',t.id):'')+action('Editar','edit-transactions',t.id)+(t.status!=='cancelled'?action('Cancelar','cancel',t.id,'danger'):'')+'</div></td></tr>').join('')+'</tbody></table></div>':empty('Nenhum lançamento neste filtro','Altere o período ou cadastre uma movimentação.');}
function transactionsPage(){return heading(action('＋ Lançamento','new-transactions','','primary compact'))+'<section class="panel">'+filters()+transactionTable(filtered())+'</section>'+(view==='future'?'<section class="panel section-gap"><div class="panel-header"><h3>Faturas em aberto neste mês</h3>'+action('Ver cartões →','goto-cards','','text-button')+'</div>'+invoiceTable(F.invoices(state).filter(g=>g.open>0&&g.month===period))+'</section>':'');}
function accountsPage(investment=false){const b=F.balances(state),accounts=state.accounts.filter(a=>!investment||['investment','saving'].includes(a.kind));return heading(action(investment?'＋ Conta de investimento':'＋ Conta','new-accounts','','primary compact'))+(investment?'<p class="muted">Aportes e resgates são transferências. Registre rendimentos efetivos separadamente; simulações não alteram os saldos.</p><div class="heading-actions" style="justify-content:start;margin:18px 0">'+action('Registrar aporte / resgate','new-transfer','','secondary')+action('Registrar rendimento','new-yield','','secondary')+'</div>':'')+(accounts.length?'<div class="cards-grid">'+accounts.map(a=>'<section class="panel account-card"><div class="panel-header">'+badge(accountKinds[a.kind])+action('Editar','edit-accounts',a.id,'text-button')+'</div><h3>'+e(a.name)+'</h3><div class="metric-value">'+F.money(b[a.id])+'</div><p class="muted" style="font-size:11px">Abertura: '+F.money(a.openingCents)+' em '+date(a.openingDate)+'</p>'+action('Movimentar','new-transactions','','text-button')+'</section>').join('')+'</div>':empty(investment?'Cadastre sua primeira reserva':'Cadastre sua primeira conta'))+'<p class="panel-note">O saldo inicial é o valor antes dos movimentos da data de abertura. Contas de investimento ficam fora da projeção do dinheiro disponível.</p>';}
function invoiceTable(inv){return inv.length?'<div class="table-wrap"><table><thead><tr><th>Cartão / fatura</th><th>Vencimento</th><th class="right">Compras</th><th class="right">Pago</th><th class="right">Em aberto</th><th>Situação</th><th></th></tr></thead><tbody>'+inv.map(g=>'<tr><td><strong>'+e(name('cards',g.cardId))+'</strong><small>'+F.monthLabel(g.month)+'</small></td><td>'+date(g.dueDate)+'</td><td class="right">'+F.money(g.purchases)+'</td><td class="right">'+F.money(g.paid)+'</td><td class="right">'+F.money(g.open)+(g.credit?'<small>Crédito: '+F.money(g.credit)+'</small>':'')+'</td><td>'+badge(g.status,g.status==='Atrasada'?'red':g.open?'amber':'')+'</td><td>'+(g.open?action('Pagar','pay-invoice',g.key,'secondary compact'):'')+'</td></tr>').join('')+'</tbody></table></div>':empty('Nenhuma fatura no período');}
function cardsPage(){return heading(action('＋ Cartão','new-cards','','primary compact'))+(state.cards.length?'<div class="cards-grid">'+state.cards.map(c=>'<section class="panel card-visual"><div class="panel-header">'+badge('CRÉDITO')+action('Editar','edit-cards',c.id,'text-button')+'</div><h3>'+e(c.name)+'</h3><p class="muted">Fechamento '+c.closingDay+' · Vencimento '+c.dueDay+'</p><div class="metric-value">'+F.money(c.limitCents)+'</div><small class="muted">Limite cadastrado · informativo</small></section>').join('')+'</div>':empty('Cadastre seu primeiro cartão'))+'<section class="panel section-gap"><div class="panel-header"><div><h3>Faturas</h3><p>Compras e pagamentos agrupados por mês de vencimento</p></div>'+monthInput()+'</div>'+invoiceTable(F.invoices(state).filter(g=>g.month===period))+'</section><p class="panel-note">Compras no dia do fechamento entram no ciclo seguinte. Confira a primeira fatura com o banco. Créditos excedentes não são transferidos automaticamente para outra fatura.</p>';}
function goalCard(g,mini=false){const progress=Math.min(100,g.savedCents/g.targetCents*100);return '<'+(mini?'div':'section')+' class="'+(mini?'':'panel')+'"><div class="panel-header"><h3>'+e(g.name)+'</h3>'+(!mini?action('Editar','edit-goals',g.id,'text-button'):'')+'</div><div style="font-size:12px"><strong>'+F.money(g.savedCents)+'</strong> <span class="muted">de '+F.money(g.targetCents)+'</span></div><div class="progress"><span style="width:'+progress+'%"></span></div><div style="display:flex;justify-content:space-between;font-size:10px;color:var(--muted)"><span>'+progress.toFixed(0)+'% concluído</span><span>'+date(g.deadline)+'</span></div></'+(mini?'div':'section')+'>';}
function goalsPage(){return heading(action('＋ Meta','new-goals','','primary compact'))+(state.goals.length?'<div class="cards-grid">'+state.goals.map(g=>goalCard(g)).join('')+'</div>':empty('Dê um nome ao seu próximo objetivo'))+'<p class="panel-note">O acumulado é atualizado manualmente e não movimenta contas. Registre também as transferências quando guardar dinheiro.</p>';}
function budgetsPage(){const items=state.budgets.filter(b=>b.month===period);return heading(monthInput()+action('＋ Limite','new-budgets','','primary compact'))+(items.length?'<div class="cards-grid">'+items.map(b=>{const spent=F.budgetSpent(state,b),progress=Math.min(100,spent/b.limitCents*100);return '<section class="panel"><div class="panel-header"><h3>'+e(name('categories',b.category))+'</h3>'+action('Editar','edit-budgets',b.id,'text-button')+'</div><div class="metric-value">'+F.money(spent)+'</div><div class="muted" style="font-size:11px">de '+F.money(b.limitCents)+' planejados</div><div class="progress '+(spent>b.limitCents?'over':'')+'"><span style="width:'+progress+'%"></span></div><p class="'+(spent>b.limitCents?'negative':'positive')+'" style="font-size:12px">'+(spent>b.limitCents?'Excedido em ':'Disponível: ')+F.money(Math.abs(b.limitCents-spent))+'</p></section>';}).join('')+'</div>':empty('Defina seus limites para este mês'))+'<p class="panel-note">Comprometido inclui despesas previstas e compras no cartão na competência escolhida. Pagamentos de fatura e transferências não entram novamente.</p>';}
function categoriesPage(){return heading(action('＋ Categoria','new-categories','','primary compact'))+(state.categories.length?'<section class="panel">'+state.categories.map(c=>'<div class="mini-row"><span class="mini-icon">≡</span><div class="grow"><strong>'+e(c.name)+'</strong></div>'+action('Editar','edit-categories',c.id,'text-button')+'</div>').join('')+'</section>':empty('Cadastre suas categorias','Exemplos: Salário, Moradia, Alimentação, Saúde e Rendimentos.'));}
function reportsPage(){const rows=F.forecast(state);return heading(action('↓ CSV','csv','','secondary compact')+action('Imprimir / PDF','print','','primary compact'))+'<section class="panel">'+filters()+transactionTable(filtered())+'</section><section class="panel section-gap"><div class="panel-header"><div><h3>Fluxo de caixa projetado</h3><p>Parte do saldo atual. Vencidos entram no primeiro mês.</p></div>'+badge('12 meses')+'</div><div class="table-wrap"><table><thead><tr><th>Mês</th><th class="right">Saldo inicial</th><th class="right">Entradas previstas</th><th class="right">Saídas previstas</th><th class="right">Faturas abertas</th><th class="right">Saldo final</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+F.monthLabel(r.month)+'</td><td class="right">'+F.money(r.opening)+'</td><td class="right">'+F.money(r.incoming)+'</td><td class="right">'+F.money(r.outgoing)+'</td><td class="right">'+F.money(r.card)+'</td><td class="right"><strong>'+amt(r.balance)+'</strong></td></tr>').join('')+'</tbody></table></div></section>';}

const moneyFields=new Set(['amount','opening','limit','target','saved','initial','contribution','cash','down','reserved']);
const input=(name,label,value='',type='text',extra='',note='')=>{
 const currency=type==='text'&&moneyFields.has(name),shown=currency?moneyValue(value):value;
 const attrs=currency?' data-money="true" data-allow-negative="'+(name==='opening')+'" inputmode="numeric" placeholder="0,00"': '';
 return '<label>'+label+'<input name="'+name+'" type="'+type+'" value="'+e(shown)+'"'+attrs+' '+(currency?extra.replace(/inputmode="[^"]*"/g,''):extra)+'>'+(note?'<small>'+note+'</small>':'')+'</label>';
};
const select=(field,label,options,value='',note='')=>'<label>'+label+'<select name="'+field+'">'+options.map(([k,v])=>'<option value="'+e(k)+'" '+(k===value?'selected':'')+'>'+e(v)+'</option>').join('')+'</select>'+(note?'<small>'+note+'</small>':'')+'</label>';
function calculatorsPage(){return heading()+'<div class="grid-two"><section class="panel calculator-panel"><h3>Seu investimento no tempo</h3><p class="muted">Juros compostos com taxa fixa hipotética.</p><form data-calc="investment">'+input('initial','Valor inicial (R$)','1000,00','text','required inputmode="decimal"')+input('contribution','Aporte mensal (R$)','200,00','text','required inputmode="decimal"')+input('rate','Taxa de juros (%)','8','number','required step="any" min="-99.99" max="1000"')+select('period','Período da taxa',[['annual','Ao ano · efetiva'],['monthly','Ao mês']],'annual')+input('months','Prazo em meses','24','number','required min="1" max="600"')+select('timing','Momento do aporte',[['end','Fim do mês'],['beginning','Início do mês']])+input('target','Meta opcional (R$)','','text','inputmode="decimal"')+'<button class="primary" type="submit">Simular investimento →</button></form><div id="investment-result" class="calc-result muted">Seu resultado aparecerá aqui.</div><p class="panel-note">Valores nominais, sem impostos, tarifas ou inflação. Taxa constante não representa garantia de rentabilidade. A simulação não movimenta suas contas.</p></section><div><section class="panel calculator-panel"><h3>À vista ou financiado?</h3><p class="muted">Parcelas fixas pela tabela Price, sem tarifas adicionais.</p><form data-calc="purchase">'+input('cash','Preço à vista (R$)','1200,00','text','required inputmode="decimal"')+input('down','Entrada (R$)','0,00','text','required inputmode="decimal"')+input('count','Número de parcelas','12','number','required min="1" max="120"')+input('rate','Juros ao mês (%)','2','number','required min="0" max="100" step="any"')+'<button class="primary" type="submit">Comparar custos →</button></form><div id="purchase-result" class="calc-result muted">Compare o total e o custo dos juros.</div><p class="panel-note">Arredondamento pode exigir ajuste de centavos na última parcela do contrato real. Não inclui IOF, seguros ou CET.</p></section><section class="panel calculator-panel section-gap"><h3>Calculadora do dia a dia</h3><form data-calc="basic">'+input('expression','Conta matemática','(125 + 75) * 10%','text','required')+'<button class="primary" type="submit">Calcular =</button></form><div id="basic-result" class="calc-result muted">Use +, −, *, /, parênteses e %. Ex.: 200 * 10% = 20.</div></section></div></div>';}
function render(){drawNav();if(!ready&&view!=='help'){$('content').innerHTML='<div class="loading">Os dados ainda não foram carregados. Use Atualizar para tentar novamente.</div>';return;}const map={payables:payablesPage,pots:potsPage,between:betweenPage,help:helpPage,settings:settingsPage,dashboard,transactions:transactionsPage,future:transactionsPage,accounts:()=>accountsPage(),cards:cardsPage,budgets:budgetsPage,goals:goalsPage,investments:()=>accountsPage(true),calculators:calculatorsPage,categories:categoriesPage,reports:reportsPage};$('content').innerHTML=map[view]();}
function go(target){if(!views[target])return;view=target;query='';typeFilter='all';statusFilter='all';layout.closeMenu({restoreFocus:false});render();$('content').focus({preventScroll:true});window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}
function options(k){return [['','Selecione…'],...state[k].map(x=>[x.id,x.name])];}
function openEditor(kind,id='',preset={}){if(kind==='transactions'&&state.transactions.find(t=>t.id===id)?.linkId)return openCross(state.transactions.find(t=>t.id===id).linkId);editorControl=Store.currentControl();if(!ready){notice('Carregue os dados antes de editar.');return;}editorKind=kind;editing=id;const found=state[kind]?.find(x=>x.id===id)||{};const t={...found,...preset};$('editor-title').textContent=controls[editorControl]+' · '+(id?'Editar ':'Novo ')+({accounts:'cadastro de conta',cards:'cartão',categories:'categoria',transactions:'lançamento',budgets:'limite de orçamento',goals:'objetivo',pots:'pote de reserva'}[kind]);let fields='';
 if(kind==='pots')fields=potFields(t);
 if(kind==='accounts')fields=input('name','Nome da conta',t.name||'','text','required maxlength="80"')+select('kind','Tipo de conta',Object.entries(accountKinds),t.kind||(view==='investments'?'investment':'checking'))+input('opening','Saldo de abertura (R$)',((t.openingCents||0)/100).toFixed(2).replace('.',','),'text','required inputmode="decimal"')+input('openingDate','Data de abertura',t.openingDate||F.today(),'date','required')+'<p class="form-info full">Informe o saldo ANTES dos movimentos da data de abertura. Saldo inicial não é receita. Alterar a abertura recalcula o histórico desta conta.</p>';
 if(kind==='cards')fields=input('name','Nome do cartão',t.name||'','text','required maxlength="80"')+input('limit','Limite cadastrado (R$)',((t.limitCents||0)/100).toFixed(2).replace('.',','),'text','required inputmode="decimal"')+input('closingDay','Dia de fechamento',t.closingDay||20,'number','required min="1" max="31"')+input('dueDay','Dia de vencimento',t.dueDay||28,'number','required min="1" max="31"')+'<p class="form-info full">Nos meses mais curtos, usamos o último dia disponível. Compras no dia do fechamento entram no ciclo seguinte. Alterar os dias afeta novas compras; parcelas já registradas mantêm suas datas.</p>';
 if(kind==='categories')fields=input('name','Nome da categoria',t.name||'','text','required maxlength="80"');
 if(kind==='budgets')fields=input('month','Mês',t.month||period,'month','required')+select('category','Categoria',options('categories'),t.category)+input('limit','Limite (R$)',t.limitCents?(t.limitCents/100).toFixed(2).replace('.',','):'','text','required inputmode="decimal"');
 if(kind==='goals')fields=input('name','Nome do objetivo',t.name||'','text','required maxlength="100"')+input('deadline','Prazo',t.deadline||F.addMonths(F.today(),12),'date','required')+input('target','Valor objetivo (R$)',t.targetCents?(t.targetCents/100).toFixed(2).replace('.',','):'','text','required inputmode="decimal"')+input('saved','Valor já acumulado (R$)',((t.savedCents||0)/100).toFixed(2).replace('.',','),'text','required inputmode="decimal"');
 if(kind==='transactions')fields=select('kind','Tipo de lançamento',Object.entries(txKinds).filter(([k])=>!k.startsWith('inter')),t.kind||'expense')+input('description','Descrição',t.description||'','text','required maxlength="200"')+input('amount','Valor '+(!id?'total ':'')+'(R$)',t.amountCents?(t.amountCents/100).toFixed(2).replace('.',','):'','text','required inputmode="decimal"')+select('category','Categoria',options('categories'),t.category)+select('accountId','Conta de origem / recebimento',options('accounts'),t.accountId)+select('toAccountId','Conta de destino',options('accounts'),t.toAccountId)+select('cardId','Cartão',options('cards'),t.cardId)+select('potId','Pote usado no pagamento (opcional)',[['','Sem pote'],...(state.pots||[]).map(p=>[p.id,p.name+' · '+name('accounts',p.accountId)])],t.potId||'')+input('date','Data do registro / compra',t.date||F.today(),'date','required')+input('dueDate','Vencimento',t.dueDate||F.today(),'date','required')+input('competence','Competência / mês da fatura',t.competence||(t.kind==='card'?'':period),'month','', 'No cartão, deixe vazio para calcular automaticamente.')+select('status','Situação',[['planned','Previsto'],['posted','Pago / Recebido / Confirmado'],['cancelled','Cancelado']],t.status||'planned')+input('paidDate','Data efetiva do pagamento / recebimento',t.paidDate||F.today(),'date','max="'+F.today()+'"')+(!id?input('installments','Parcelas no cartão (divide o total)','1','number','required min="1" max="120"')+input('repetitions','Ocorrências mensais (repete o valor)',t.repetitions||'1','number','required min="1" max="120"'):'')+'<p class="form-info full">'+(id?'A edição altera somente esta ocorrência. Para desfazer uma baixa, escolha Previsto.':'Recorrências incluem a primeira ocorrência. Crie contas recorrentes como Previsto e baixe cada uma depois.')+' Compra no cartão forma a fatura; registre o pagamento como Pagamento de fatura, sem criar outra despesa.</p>';
 $('editor-fields').innerHTML=fields+(fields.includes('data-money=')?'<p class="form-info full">Valores em reais: digite só números. Ex.: 2000 → 20,00; 123456 → 1.234,56. Ao colar o valor inteiro, 20 é interpretado como R$ 20,00.</p>':'');$('editor-error').textContent='';$('editor').showModal();syncControlHeader();if(kind==='transactions')syncTxFields();}
function syncTxFields(){const form=$('editor-form'),k=form.elements.kind.value;const show=(field,visible)=>{const el=form.elements[field];if(el)el.closest('label').hidden=!visible;};show('potId',['expense','invoicePayment'].includes(k));show('category',['income','expense','card','yield'].includes(k));show('accountId',k!=='card');show('toAccountId',k==='transfer');show('cardId',['card','invoicePayment'].includes(k));show('paidDate',k!=='card'&&form.elements.status.value==='posted');show('installments',k==='card');show('repetitions',!['card','invoicePayment','transfer'].includes(k));show('dueDate',!['card','invoicePayment'].includes(k));}
async function reload(){
 const sequence=++reloadSequence,control=Store.currentControl();ready=false;state=F.emptyState();links=[];$('new-transaction').disabled=true;render();
 try{const loaded=await loginDeadline(Promise.all([Store.readState(),Store.readLinks()]),20000,'app/data-timeout');if(sequence!==reloadSequence||control!==Store.currentControl())return;[state,links]=loaded;ready=true;render();notice('');}
 catch(err){if(sequence===reloadSequence){render();notice(errorText(err));}}
 finally{if(sequence===reloadSequence){$('new-transaction').disabled=!ready;syncControlHeader();}}
}
async function saveEditor(ev){ev.preventDefault();const form=$('editor-form');if(!form.reportValidity())return;const f=Object.fromEntries(new FormData(form));const id=editing||crypto.randomUUID();let rows=[];const existing=state[editorKind]?.find(x=>x.id===id);$('save-editor').disabled=true;$('editor-error').textContent='';editorSaving=true;syncControlHeader();try{
 if(editorControl!==Store.currentControl())throw Error('O controle mudou. Abra o formulário novamente.');
 if(editorKind==='potAllocation'){await Store.changeReserve(id,F.cents(f.amount),allocationMode);$('editor').close();await reload();if(ready)notice(allocationMode==='reserve'?'Dinheiro reservado no pote. O saldo da conta permanece o mesmo.':'Reserva liberada. O valor voltou a ficar não reservado na mesma conta.',true);return;}
 if(editorKind==='links'){await saveCross(f,id);$('editor').close();await reload();if(ready)notice('Movimentação registrada nos dois controles.',true);return;}
 if(editorKind==='pots')rows=[potRow(f,id,existing)];
 if(editorKind==='accounts'){if(!F.validDate(f.openingDate)||f.openingDate>F.today())throw Error('A data de abertura deve ser válida e não pode estar no futuro.');rows=[{id,name:f.name.trim(),kind:f.kind,openingCents:F.cents(f.opening,true),openingDate:f.openingDate}];}
 if(editorKind==='cards'){const closingDay=Number(f.closingDay),dueDay=Number(f.dueDay);if(![closingDay,dueDay].every(n=>Number.isInteger(n)&&n>=1&&n<=31))throw Error('Dias entre 1 e 31.');rows=[{id,name:f.name.trim(),limitCents:F.cents(f.limit),closingDay,dueDay}];}
 if(editorKind==='categories')rows=[{id,name:f.name.trim()}];
 if(['accounts','cards','categories'].includes(editorKind)&&(!f.name.trim()||state[editorKind].some(x=>x.id!==id&&x.name.toLowerCase()===f.name.trim().toLowerCase())))throw Error('Use um nome preenchido e diferente dos demais.');
 if(editorKind==='budgets'){const limit=F.cents(f.limit);if(!limit||!state.categories.some(x=>x.id===f.category)||!F.validDate(f.month+'-01'))throw Error('Confira mês, categoria e limite positivo.');if(state.budgets.some(b=>b.id!==id&&b.category===f.category&&b.month===f.month))throw Error('Já existe um limite para esta categoria neste mês.');rows=[{id,month:f.month,category:f.category,limitCents:limit}];}
 if(editorKind==='goals'){const target=F.cents(f.target);if(!f.name.trim()||target<=0||!F.validDate(f.deadline))throw Error('Confira nome, objetivo positivo e prazo.');rows=[{id,name:f.name.trim(),targetCents:target,savedCents:F.cents(f.saved),deadline:f.deadline}];}
 if(editorKind==='transactions'){
 const amount=F.cents(f.amount),n=editing?1:Number(f.installments||1),repeat=editing?1:Number(f.repetitions||1),k=f.kind;
 if(!Number.isInteger(n)||!Number.isInteger(repeat)||n<1||repeat<1||n>120||repeat>120)throw Error('Use de 1 a 120 parcelas ou ocorrências.');
 const count=k==='card'?n:repeat;if(k==='card'&&repeat>1)throw Error('Não combine parcelas e recorrências.');if(k!=='card'&&n>1)throw Error('Parcelamento é exclusivo de compras no cartão.');if(['invoicePayment','transfer'].includes(k)&&repeat>1)throw Error('Registre cada pagamento ou transferência individualmente.');if(count>1&&k!=='card'&&f.status!=='planned')throw Error('Crie recorrências como Previsto.');
 let due=f.dueDate,comp=f.competence||f.dueDate.slice(0,7);const card=state.cards.find(c=>c.id===f.cardId);
 if(['card','invoicePayment'].includes(k)){if(!card)throw Error('Escolha um cartão.');if(k==='invoicePayment'&&!f.competence)throw Error('Informe o mês da fatura paga.');due=F.cardDue(card,f.date,f.competence||'');comp=due.slice(0,7);const invoice=F.invoices(state).find(g=>g.cardId===card.id&&g.month===comp);if(k==='invoicePayment'&&invoice)due=invoice.dueDate;}
 const parts=k==='card'?F.splitCents(amount,count):Array(count).fill(amount);
 for(let i=0;i<count;i++){const t={id:i===0?id:crypto.randomUUID(),kind:k,description:f.description.trim(),amountCents:parts[i],potId:['expense','invoicePayment'].includes(k)?f.potId||'':'',category:['income','expense','card','yield'].includes(k)?f.category:'',accountId:k==='card'?'':f.accountId,toAccountId:k==='transfer'?f.toAccountId:'',cardId:['card','invoicePayment'].includes(k)?f.cardId:'',date:f.date,dueDate:F.addMonths(due,i),competence:F.addMonths(comp+'-01',i).slice(0,7),paidDate:f.status==='posted'&&k!=='card'?f.paidDate:'',status:f.status,groupId:existing?.groupId||id,installment:existing?.installment||i+1,installments:existing?.installments||count};F.validateTx(t,state);rows.push(t);}
 if(k==='invoicePayment'&&f.status==='posted'){const without={...state,transactions:state.transactions.filter(t=>t.id!==id)};const invoice=F.invoices(without).find(g=>g.cardId===f.cardId&&g.month===comp);if(!invoice||amount>invoice.open)throw Error('O pagamento excede o saldo aberto da fatura. Confira cartão, mês e valor.');}
 }
 await Store.saveRows(editorKind,rows);$('editor').close();await reload();if(ready)notice('Registro salvo com sucesso.',true);
 }catch(err){$('editor-error').textContent=errorText(err);}finally{editorSaving=false;$('save-editor').disabled=false;syncControlHeader();}}
function download(name,text,type='application/json'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function csv(){const cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'"+'$&').replace(/"/g,'""')+'"';const rows=[['Vencimento','Baixa','Descrição','Tipo','Categoria','Conta','Cartão','Valor (R$)','Situação'],...filtered().map(t=>[t.dueDate,t.paidDate,t.description,txLabel(t),name('categories',t.category),name('accounts',t.accountId),name('cards',t.cardId),(t.amountCents/100).toFixed(2).replace('.',','),t.status])];download('extrato-'+period+'.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
async function onAction(act,id){try{
 if(act==='reserve-pot')return openReserve(id,'reserve');
 if(act==='release-pot')return openReserve(id,'release');
 if(act==='new-fixed')return openEditor('transactions','',{kind:'expense',status:'planned',repetitions:12});
 if(act==='new-payable')return openEditor('transactions','',{kind:'expense',status:'planned'});
 if(act==='new-cross')return openCross();
 if(act==='edit-cross')return openCross(id);
 if(act==='settle-cross')return openCross(id,true);
 if(act==='cancel-cross'){const link=links.find(l=>l.id===id);if(link&&confirm('Cancelar esta movimentação nos DOIS controles?')){await Store.saveLink({...link,status:'cancelled'});await reload();}return;}
 if(act==='planning-month'){if(!F.validDate(id+'-01'))return;period=id;return go('future');}
 if(act==='reset-movements')return startReset('movements');
 if(act==='reset-all')return startReset('all');
 if(act.startsWith('goto-'))return go(act.slice(5));if(act.startsWith('new-')&&!['new-transfer','new-yield'].includes(act))return openEditor(act.slice(4));if(act.startsWith('edit-'))return openEditor(act.slice(5),id);
 if(act==='new-transfer')return openEditor('transactions','',{kind:'transfer'});
 if(act==='new-yield')return openEditor('transactions','',{kind:'yield',status:'posted'});
 if(act==='settle'){const t=state.transactions.find(t=>t.id===id);if(t?.linkId)return openCross(t.linkId,true);return openEditor('transactions',id,{...t,status:'posted',paidDate:F.today()});}
 if(act==='cancel'){const t=state.transactions.find(t=>t.id===id);if(t?.linkId)return onAction('cancel-cross',t.linkId);if(t&&confirm('Cancelar somente este registro? O histórico será preservado.')){await Store.saveRows('transactions',[{...t,status:'cancelled'}]);await reload();}return;}
 if(act==='pay-invoice'){const g=F.invoices(state).find(g=>g.key===id);return openEditor('transactions','',{kind:'invoicePayment',description:'Pagamento de fatura '+name('cards',g.cardId),cardId:g.cardId,competence:g.month,dueDate:g.dueDate,amountCents:g.open,status:'posted'});}
 if(act==='csv')csv();if(act==='print')window.print();
 }catch(err){notice(errorText(err));}}
function doCalculation(form){const f=Object.fromEntries(new FormData(form)),kind=form.dataset.calc,out=$(kind+'-result');try{if(kind==='investment'){const initial=F.cents(f.initial),contribution=F.cents(f.contribution),rows=F.investmentSimulation({initial,contribution,rate:Number(f.rate),period:f.period,months:Number(f.months),beginning:f.timing==='beginning'}),last=rows.at(-1),target=f.target?F.cents(f.target):0,hit=target?rows.find(r=>r.balance>=target):null;out.innerHTML='<span class="muted">Saldo estimado ao final</span><div class="big">'+F.money(last.balance)+'</div><div class="calc-breakdown"><span>Capital aplicado<strong>'+F.money(last.invested)+'</strong></span><span>Rendimento estimado<strong>'+F.money(last.yield)+'</strong></span></div>'+(target?'<p style="font-size:12px">'+(initial>=target?'Meta já alcançada no valor inicial.':hit?'Meta alcançada no mês '+hit.month+'.':'Meta não alcançada nesse prazo.')+'</p>':'');}else if(kind==='purchase'){const result=F.purchaseSimulation(F.cents(f.cash),F.cents(f.down),Number(f.count),Number(f.rate));out.innerHTML='<div class="big">'+f.count+' × '+F.money(result.payment)+'</div><div class="calc-breakdown"><span>Total com entrada<strong>'+F.money(result.total)+'</strong></span><span>Juros estimados<strong>'+F.money(result.interest)+'</strong></span></div>'+(result.lastPayment!==result.payment?'<p style="font-size:11px">Última parcela ajustada: '+F.money(result.lastPayment)+'</p>':'');}else out.textContent=F.calculate(f.expression).toLocaleString('pt-BR',{maximumFractionDigits:10});}catch(err){out.textContent=errorText(err);}}
async function enter(user){
 const sequence=++entrySequence;
 try{
  if(!Store.isDemo())$('auth-message').textContent='E-mail e senha aceitos. Verificando sua autorização no Firestore…';
  await loginDeadline(Store.assertAccess(),15000,'app/access-timeout');
  if(sequence!==entrySequence)return;
  $('login-screen').hidden=true;$('app-shell').hidden=false;
  $('user-label').textContent=user.email||'Minha conta';layout.syncAccount();
  $('mode-label').textContent=Store.isDemo()?'Demonstração local':'Conta sincronizada';
  $('demo-banner').hidden=!Store.isDemo();
  $('password').value='';
  await reload();
 }catch(err){
  if(sequence!==entrySequence)return;
  ready=false;state=F.emptyState();
  try{await Store.logout();}catch(signOutError){}
  $('app-shell').hidden=true;$('login-screen').hidden=false;
  $('auth-message').textContent=errorText(err);
 }
}
