 return heading()+'<section class="panel help-intro"><div><span class="eyebrow teal">UM GUIA PARA O SEU DIA A DIA</span><h2>Como usar o Meu Financeiro</h2><p>Encontre uma tarefa, veja o passo a passo e abra a área correspondente. Este guia explica o que o aplicativo faz hoje.</p></div><label class="help-search-label">Buscar na ajuda<input id="help-search" type="search" placeholder="Ex.: cartão, saldo inicial, despesas futuras…" autocomplete="off"></label><p id="help-count" class="muted" role="status">'+helpTopics.length+' tópicos disponíveis</p></section>'+
 '<div class="help-quick-links">'+['accounts','transactions','cards','dashboard'].map(key=>'<button class="secondary compact" data-view="'+key+'">'+e(views[key][1])+' →</button>').join('')+'</div>'+
 '<div class="help-topics">'+helpTopics.map(topic=>'<details class="panel help-topic" data-help-id="'+topic.id+'"><summary>'+e(topic.title)+'</summary><ol>'+topic.steps.map(step=>'<li>'+e(step)+'</li>').join('')+'</ol><button class="secondary compact" data-view="'+topic.view+'">Abrir '+e(views[topic.view][1])+' →</button></details>').join('')+'</div>'+
 '<div id="help-empty" class="panel empty" hidden><strong>Nenhum tópico encontrado</strong><p>Tente outra palavra, como fatura, conta, previsão ou backup.</p></div>';
