function filterHelp(query){
 const matches=new Set(searchHelp(query).map(topic=>topic.id));
 $('content').querySelectorAll('[data-help-id]').forEach(element=>{const visible=matches.has(element.dataset.helpId);element.hidden=!visible;if(query.trim()&&visible)element.open=true;});
 $('help-count').textContent=matches.size+' tópico(s) encontrado(s)';
 $('help-empty').hidden=matches.size>0;
}

