 return heading(monthInput()+action('＋ Conta a pagar','new-payable','','primary compact')+action('↻ Conta fixa mensal','new-fixed','','secondary compact'))+'<div class="metrics">'+metric('Contas pendentes',plan.expenses,rows.length+' conta(s) neste mês','◷')+metric('Faturas abertas',plan.invoices,inv.length+' fatura(s) neste mês','▱')+metric('Total a pagar',plan.toPay,'Somente '+e(controls[Store.currentControl()]),'↗',true)+metric('De hoje em diante',plan.futureTotal,plan.futureCount+' compromisso(s) registrado(s)','◷')+'</div><section class="panel"><div class="panel-header"><h2>Contas com vencimento em '+e(F.monthLabel(period))+'</h2></div>'+transactionTable(rows)+'</section><section class="panel section-gap"><h3>Faturas do mês</h3>'+invoiceTable(inv)+'</section><p class="panel-note">Conta fixa mensal cria 12 ocorrências previstas por padrão; ajuste de 1 a 120. Cada ocorrência recebe sua própria data e baixa. Não há criação infinita nem notificação com o aplicativo fechado. Consulte os próximos meses no seletor.</p>';
