function potsPage(){const summary=reserveSummary(state);return heading(action('＋ Pote','new-pots','','primary compact'))+'<div class="metrics">'+metric('Saldo nas contas',summary.total,'Inclui o dinheiro já reservado','▤')+metric('Reservado nos potes',summary.reserved,'Parte do saldo das contas','▣')+metric('Ainda não reservado',summary.unallocated,'Não é cálculo de lucro disponível','↗',true)+'</div>'+(state.pots.length?'<div class="cards-grid">'+state.pots.map(p=>{const balance=potBalance(state,p);return '<section class="panel"><div class="panel-header"><h3>'+e(p.name)+'</h3>'+action('Editar pote','edit-pots',p.id,'text-button')+'</div><p class="muted">'+e(name('accounts',p.accountId))+'</p><div class="metric-value">'+F.money(balance)+'</div><p>Objetivo: '+F.money(p.targetCents)+' · Falta: '+F.money(Math.max(0,p.targetCents-balance))+'</p><div class="heading-actions">'+action('Reservar dinheiro','reserve-pot',p.id,'primary compact')+action('Liberar reserva','release-pot',p.id,'secondary compact')+'</div></section>';}).join('')+'</div>':empty('Dê uma finalidade ao dinheiro','Exemplos: despesas operacionais, folha de pagamento, impostos e reserva de segurança.'))+'<p class="panel-note">Use Reservar dinheiro para acrescentar uma quantia do saldo não reservado da mesma conta ao pote. Liberar reserva devolve uma quantia ao saldo não reservado. Nenhuma dessas ações é receita ou despesa e o saldo bancário não muda. Em Editar pote, o campo reservado define o total do pote. Ao pagar uma despesa ou fatura, selecione o pote da mesma conta: o pagamento reduz a conta e consome a reserva uma única vez. Para transferir dinheiro reservado, libere a reserva antes.</p>';}
